  it.each(['accepted', 'tool-running', 'stale-shell', 'residue', 'refused', 'new-question', 'draft'])('direct delivery reaches the claimed running turn without clicking Stop (%s)', async change => {
    const accepted = ['accepted', 'tool-running', 'stale-shell', 'residue'].includes(change);
    let directTurn: { id: string; startedAt: number };
    live = await nonProHarness(`https://chatgpt.com/c/${chatA}`, {
      desktop_input: message => {
        if (message.authorize || message.ack || message.fail) return { ok: true, data: { ok: true } };
        if (change === 'new-question') { userTurn(live!.document, 'new-question', 'A later user instruction'); live!.hook.observe(); }
        return { ok: true, data: { input: change === 'refused' ? null : claimed({ directTurn }) } };
      }
    });
    startGenerating(live.document);
    if (change === 'stale-shell') {
      const shell = live.document.createElement('main');
      shell.setAttribute('data-app-shell-main-surface', 'true');
      shell.innerHTML = `<div data-thread-find-target="conversation"><div data-turn-key="direct-source" data-clf-shell-running="${live.window.location.pathname}"><div data-chatgpt-agent-turn-start="true"></div></div></div>`;
      live.document.body.append(shell);
    }
    live.hook.observe(); await live.hook.flush();
    const start = emitted(live.sent, 'turn_start').at(-1)!;
    directTurn = { id: start.event.turnId as string, startedAt: start.event.time as number };
    if (change === 'tool-running') {
      live.reply.set('activity', () => ({ ok: true, data: { stream: [], entries: [], pendingTools: 1,
        activeTurnId: directTurn.id } }));
      await live.hook.pullActivity();
    }
    const stops = vi.fn(() => { void settleTurn(live!); });
    const stop = live.document.querySelector('[data-testid="stop-button"]')!;
    Object.defineProperty(stop, 'getClientRects', { value: () => [{ width: 32, height: 32 }] });
    stop.addEventListener('click', stops);
    const sends = watchSend(live.document);
    live.document.querySelector('[data-testid="send-button"]')!.addEventListener('click', () => {
      userTurn(live!.document, 'direct-correction', text, { sent: false });
      live!.document.querySelector('#prompt-textarea')!.textContent = '';
    });
    if (change === 'draft') live.document.querySelector('#prompt-textarea')!.textContent = 'My own substantive draft';
    if (change === 'residue') live.document.querySelector('#prompt-textarea')!.textContent = 'abc def ghi';
    expect(await live.runtimeMessage({ type: 'clf-desktop-input', id: inputId, conversationId: chatA, directTurn }),
      JSON.stringify(live.sent.filter(message => message.type === 'desktop_input')))
      .toEqual({ ok: accepted });
    expect(stops).toHaveBeenCalledTimes(0);
    expect(sends()).toBe(accepted ? 1 : 0);
    expect(live.sent.filter(message => message.ack)).toHaveLength(accepted ? 1 : 0);
    if (change === 'draft') expect(composerText(live.document)).toBe('My own substantive draft');
  });
