  it.each([
    { name: 'its own Temporary Chat request', temporary: true, evidence: 'own', accepted: true },
    { name: 'an ordinary chat without a route', temporary: false, evidence: 'own', accepted: false },
    { name: 'a request before the native click', temporary: true, evidence: 'stale', accepted: false },
    { name: 'a delayed request captured before the native click', temporary: true, evidence: 'delayed-old', accepted: false },
    { name: 'a request with a future capture time', temporary: true, evidence: 'future-time', accepted: false },
    { name: 'a request without capture time', temporary: true, evidence: 'missing-time', accepted: false },
    { name: 'an expired asynchronous request capture', temporary: true, evidence: 'expired-time', accepted: false },
    { name: 'a request from another origin', temporary: true, evidence: 'foreign-origin', accepted: false },
    { name: 'a request from another window', temporary: true, evidence: 'foreign-window', accepted: false },
    { name: 'more than one provider user id', temporary: true, evidence: 'ambiguous', accepted: false },
    { name: 'an invalid provider user id', temporary: true, evidence: 'invalid', accepted: false },
    { name: 'a request after the document epoch changed', temporary: true, evidence: 'changed-epoch', accepted: false }
  ] as const)('keeps null-route provider Send receipt custody exact: $name', async ({ temporary, evidence, accepted }) => {
    const submitted = prepareOperatorPrompt('Collect this exact helper decision without recording its private transcript.', upper => upper - 1);
    const questionId = '6ac024bb-486c-83e8-bf8e-4be1147847d3';
    const root = 'https://chatgpt.com/?' + (temporary ? 'temporary-chat=true&' : '') + 'cos-input=' + inputId;
    live = await harness(root, {
      desktop_input: message => ({ ok: true, data: message.authorize || message.ack || message.stage || message.response
        ? { ok: true } : { input: claimed({ text: submitted,
          ...(temporary ? { purpose: 'decision', lifetime: 'temporary-planner', model: 'gpt-6-thinking', reasoningEffort: 'high' } : {}) }) } })
    });
    if (temporary) {
      const header = live.document.createElement('div'); header.dataset.testid = 'app-shell-header-context-menu-surface';
      const toggle = live.document.createElement('button'); toggle.setAttribute('aria-label', 'Turn off temporary chat');
      header.append(toggle); live.document.body.prepend(header);
      for (const node of [header, toggle, live.document.querySelector('form')!])
        node.getClientRects = () => [{ width: 100, height: 20 }] as unknown as DOMRectList;
    }
    const sendRequest = () => live!.window.dispatchEvent(new live!.window.MessageEvent('message', {
      source: evidence === 'foreign-window' ? null : live!.window as unknown as Window,
      origin: evidence === 'foreign-origin' ? 'https://example.com' : 'https://chatgpt.com',
      data: { type: 'cos-send-request', observedAt: evidence === 'missing-time' ? undefined : live!.window.Date.now() + (evidence === 'future-time' ? 1000 : evidence === 'delayed-old' ? -1000 : evidence === 'expired-time' ? -15000 : 0), messageIds: evidence === 'ambiguous'
        ? [questionId, '11111111-2222-4333-8444-555555555555']
        : [evidence === 'invalid' ? 'not-a-provider-message-id' : questionId] }
    }));
    if (evidence === 'stale') {
      sendRequest();
      await new Promise(resolve => live!.window.setTimeout(resolve, 5));
    }
    const click = vi.fn(() => {
      live!.document.querySelector('#prompt-textarea')!.textContent = '';
      startGenerating(live!.document, { send: false });
      if (evidence === 'changed-epoch') {
        live!.dom.reconfigure({ url: 'https://chatgpt.com/c/' + chatB });
        live!.hook.observe();
        live!.dom.reconfigure({ url: root });
        live!.hook.observe();
      }
      if (evidence !== 'stale') sendRequest();
    });
    live.document.querySelector('[data-testid="send-button"]')!.addEventListener('click', click);

    expect(await live.runtimeMessage({ type: 'clf-desktop-input', id: inputId, conversationId: null,
      ...(temporary ? { lifetime: 'temporary-planner' } : {}) })).toEqual({ ok: accepted });
    expect(click).toHaveBeenCalledOnce();
    expect(live.sent.filter(message => message.type === 'desktop_input' && message.authorize)).toHaveLength(1);
    expect(live.sent.filter(message => message.type === 'desktop_input' && message.ack)).toEqual(accepted ? [
      expect.objectContaining({ id: inputId, owner: 'input-owner', conversationId: null, messageId: questionId,
        lifetime: 'temporary-planner' })
    ] : []);
    // The request owns only Send custody. No answer or rendered message exists yet.
    expect((live.window as any).CLF_DOM.messages()).toEqual([]);
    expect(live.document.querySelector('[data-testid="stop-button"]')).not.toBeNull();
    expect(live.sent.filter(message => message.response || message.partial)).toEqual([]);
    if (temporary) {
      await live.hook.flush();
      expect(emitted(live.sent, 'user_message')).toEqual([]);
      expect(emitted(live.sent, 'assistant_message')).toEqual([]);
      expect(live.sent.filter(message => message.type === 'correlate')).toEqual([]);
    }
  });

