  it('accepts ChatGPT Markdown serialization of the exact framed opening prompt', async () => {
    const url = 'https://prism.openai.com/?u=a9e25130-d1bd-493f-b132-9fa031822239&pg=1&m=main.tex';
    const authored = `Research this page without changing the workspace:\n\n${url}`;
    const prompt = prepareOperatorPrompt(prependUserPrompt(authored, '# Core guidance\n- Use `read` first.\n<INSTRUCTIONS>Keep exact ownership.</INSTRUCTIONS>'), upper => upper - 1);
    // Live ChatGPT evidence: its provider user object escaped Markdown punctuation and
    // serialized the authored bare URL as an equivalent Markdown link. The rendered bubble
    // had already consumed the source punctuation, so neither representation was byte-equal
    // to the exact composer text even though this was the row created by that native Send.
    const provider = prompt.replace(url, `[${url}](${url})`).replace(/([_`#<>&*()-])/g, '\\$1');
    const rendered = prompt.replace(/[`#*<>]/g, '').replace(/^\s*-\s*/gm, '').replace(url, url);
    live = await harness(`https://chatgpt.com/?cos-input=${inputId}`, {
      desktop_input: message => ({ ok: true, data: message.authorize || message.ack
        ? { ok: true } : { input: claimed({ text: prompt }) } })
    }, undefined, false, true);
    let user!: HTMLElement;
    let clicked!: () => void;
    const click = new Promise<void>(resolve => { clicked = resolve; });
    live.document.querySelector('[data-testid="send-button"]')!.addEventListener('click', () => {
      live!.dom.reconfigure({ url: `https://chatgpt.com/c/${chatA}` });
      const notice = live!.document.createElement('div');
      notice.setAttribute('role', 'dialog');
      Object.defineProperty(notice, 'getClientRects', { value: () => [{ width: 400, height: 200 }] });
      notice.innerHTML = '<h2>Too many requests</h2><p>We have temporarily limited access to conversations.</p>';
      live!.document.body.append(notice);
      user = userTurn(live!.document, 'serialized-framed-user', rendered, { sent: false });
      live!.document.querySelector('#prompt-textarea')!.textContent = '';
      clicked();
    });
    const delivery = live.runtimeMessage({ type: 'clf-desktop-input', id: inputId, conversationId: null });
    await click;
    await bindFiberTurns([{ section: user, turn: { turnId: 'serialized-framed-user', conversationId: chatA,
      messages: [{ role: 'user', stable: true, messageId: 'm-serialized-framed-user',
        rawMessageId: 'm-serialized-framed-user', rawText: provider }] } }], true);
    await settle(100);
    if (!live.sent.some(message => message.type === 'desktop_input' && message.ack)) {
      // Release the old implementation's unbounded post-click receipt wait so the
      // regression fails on behavior instead of timing out the whole test process.
      live.dom.reconfigure({ url: `https://chatgpt.com/c/${chatB}` });
      live.hook.observe(); user.remove();
    }
    expect(await delivery).toEqual({ ok: true });
    expect(live.sent.filter(message => message.type === 'desktop_input' && message.ack)).toEqual([
      expect.objectContaining({ conversationId: chatA, messageId: 'm-serialized-framed-user' })
    ]);
  });

