  it('does not adopt a successor route that changed before the native Resume click', async () => {
    const commandId = 'cmd-route-before-resume-click';
    const sourceConversationId = 'cccccccc-dddd-4eee-8fff-000000000000';
    const destinationConversationId = 'dddddddd-eeee-4fff-8000-111111111111';
    const token = 'abcdef0123456789abcdef0123456789';
    const prompt = prepareOperatorPrompt(`[[CLF-RESUME:${token}]]\nDo not claim a route without native Send`, upper => upper - 1);
    const clicks = vi.fn();
    let moved = false;
    live = await harness(`https://chatgpt.com/?clf=${commandId}`, {
      redeem: () => ({ ok: true, command: {
        id: commandId,
        type: 'resume',
        text: prompt,
        agent: null,
        sourceConversationId
      } }),
      compact: message => message.destinationAttempt ? { ok: true, data: { allowed: true } }
        : message.destinationDispatch ? { ok: true, data: { armed: true } }
        : message.destinationLost ? { ok: true, data: { released: true } }
        : { ok: false, error: 'unexpected_compact_shape' },
      tab_conversation: () => ({ ok: true, conversationId: destinationConversationId }),
      ack: () => ({ ok: true, status: 200, data: { committed: true, outcome: 'committed' } })
    }, document => {
      document.querySelector('[data-testid="send-button"]')!.addEventListener('click', clicks);
    }, false, true);
    const nativeSetItem = live.window.Storage.prototype.setItem;
    vi.spyOn(live.window.Storage.prototype, 'setItem').mockImplementation(function (this: Storage, key: string, value: string) {
      nativeSetItem.call(this, key, value);
      if (key !== 'clf-resume-ack-v1' || moved) return;
      moved = true;
      live!.window.queueMicrotask(() => live!.dom.reconfigure({
        url: `https://chatgpt.com/c/${destinationConversationId}`
      }));
    });

    await new Promise(resolve => globalThis.setTimeout(resolve, 750));
    await settle(400);

    expect(clicks).not.toHaveBeenCalled();
    expect(live.sent.filter(message => message.type === 'compact' && message.destinationLost)).toEqual([
      expect.objectContaining({ token, commandId })
    ]);
    expect(live.sent.some(message => message.type === 'ack' && message.status === 'sent')).toBe(false);
    expect(live.sent.some(message => message.type === 'ack' && message.status === 'attention')).toBe(false);
    expect(live.window.sessionStorage.getItem('clf-resume-ack-v1')).toBeNull();
  });

