  it('keeps a terminal resume ACK tombstone when its virtualized marker is unmounted across reinjection', async () => {
    const commandId = 'cmd-terminal-ack-reinject';
    const token = 'dcbaabcd12344321dcbaabcd12344321';
    const prompt = prepareOperatorPrompt(`[[CLF-RESUME:${token}]]\nContinue the terminal-ACK fixture.`, upper => upper - 1);
    let clicks = 0;
    let ackCalls = 0;
    let resumeSection!: HTMLElement;
    live = await harness(`https://chatgpt.com/?clf=${commandId}`, {
      redeem: () => ({ ok: true, command: { id: commandId, type: 'resume', text: prompt, agent: null } }),
      ack: () => {
        ackCalls++;
        return { ok: false, status: 409, data: { error: 'no_such_command' } };
      }
    }, (document, dom) => {
      document.querySelector('[data-testid="send-button"]')!.addEventListener('click', () => {
        clicks++;
        dom.reconfigure({ url: `https://chatgpt.com/c/${chatA}` });
        resumeSection = userTurn(document, 'terminal-resume-user', prompt, { sent: false });
        document.querySelector('#prompt-textarea')!.textContent = '';
      });
    }, false, true);

    await settle(300);
    expect(clicks).toBe(1);
    expect(ackCalls).toBe(1);
    expect(JSON.parse(live.window.sessionStorage.getItem('clf-resume-ack-v1') || 'null')).toMatchObject({
      commandId,
      token,
      terminalBlocked: true
    });

    // ChatGPT virtualizes older transcript rows. Only a later user row remains mounted when the
    // replacement recorder starts, but the route still names this same destination chat.
    resumeSection.remove();
    expect(resumeSection.isConnected).toBe(false);
    const successor = await reinjectContentRecorder(live);
    userTurn(live.document, 'question-behind-terminal-gate', 'Do not publish this as a shadow session.', { sent: false });
    successor.observe();
    await settle(100);
    await successor.flush();
    expect(ackCalls).toBe(1);
    expect(emitted(live.sent, 'user_message').map(({ event }) => event.text))
      .not.toContain('Do not publish this as a shadow session.');
    expect(live.window.sessionStorage.getItem('clf-resume-ack-v1')).toContain('terminalBlocked');

    // An authoritative app answer for the exact stable marker is the canonical release. It
    // retires the tombstone and drains the journal without ever retrying native Send or ACK.
    live.reply.set('compact', message => message.destinationMessageId
      ? { ok: false, status: 409, data: { error: 'no_such_continuation' } }
      : { ok: false, error: 'unexpected_compact_shape' });
    await bindFiberTurns([{ section: resumeSection, turn: {
      turnId: 'terminal-resume-turn',
      conversationId: chatA,
      messages: [{ role: 'user', stable: true, messageId: 'm-terminal-resume-user',
        rawMessageId: 'm-terminal-resume-user', rawText: prompt }]
    } }]);
    await settle(100);
    await successor.flush();

    expect(ackCalls).toBe(1);
    expect(clicks).toBe(1);
    expect(live.window.sessionStorage.getItem('clf-resume-ack-v1')).toBeNull();
    expect(emitted(live.sent, 'user_message').map(({ event }) => event.text))
      .toContain('Do not publish this as a shadow session.');
  });

