  it.each(['fiber', 'dom'] as const)('retains the exact canonical user body across a later DOM-only frame (%s)', async publisher => {
    live = await harness();
    const id = 'a92b4601-1111-4111-8111-000000000001';
    const canonical = 'Retain **the exact original scope**, `code`, and every acceptance requirement.\n'.repeat(120).trimEnd();
    const presentation = 'Retain the exact original scope, code, and every acceptance requirement.';
    const user = userTurn(live.document, 'canonical-user-body', publisher === 'fiber' ? presentation : canonical, { sent: false });
    user.querySelector('[data-message-id]')!.setAttribute('data-message-id', id);
    live.hook.observe(); await live.hook.flush();
    const rows = () => emitted(live!.sent, 'user_message').filter(row => row.event.messageId === id);
    expect(rows().at(-1)?.event).toMatchObject({ text: publisher === 'fiber' ? presentation : canonical, textOrigin: 'rendered' });

    await bindFiberTurns([{ section: user, turn: { turnId: 'canonical-user-body', conversationId: chatA,
      messages: [{ role: 'user', stable: true, messageId: id, rawMessageId: id, rawText: canonical }] } }]);
    live.hook.observe(); await live.hook.flush();
    expect(rows().at(-1)?.event).toMatchObject({ text: canonical, textOrigin: 'provider' });
    const beforeFallback = rows().length;
    // The next provider frame no longer exposes the user object, while the mounted
    // native row keeps its exact UUID but only has transformed presentation text.
    await bindFiberTurns([{ section: user, turn: { turnId: 'canonical-user-body', conversationId: chatA, messages: [] } }]);
    user.querySelector('.whitespace-pre-wrap')!.textContent = 'Native presentation retained the original scope and code.';
    live.hook.observe(); await live.hook.flush();
    expect(rows()).toHaveLength(beforeFallback);
    expect(rows().at(-1)?.event.text).toBe(canonical);
    live.window.dispatchEvent(new live.window.MessageEvent('message', {
      source: live.window as unknown as Window, origin: 'https://chatgpt.com',
      data: { type: 'cos-send-model', model: 'gpt-6-thinking', messageIds: [id] }
    }));
    await live.hook.flush();
    expect(rows().at(-1)?.event).toMatchObject({ text: canonical, textOrigin: 'provider', model: 'gpt-6-thinking' });

    // A genuine current provider revision remains authoritative even when shorter.
    const revised = 'Human changed the scope; retain this exact native revision.';
    await bindFiberTurns([{ section: user, turn: { turnId: 'canonical-user-body', conversationId: chatA,
      messages: [{ role: 'user', stable: true, messageId: id, rawMessageId: id, rawText: revised }] } }]);
    await live.hook.flush();
    expect(rows().at(-1)?.event.text).toBe(revised);
    await bindFiberTurns([{ section: user, turn: { turnId: 'canonical-user-body', conversationId: chatA,
      messages: [{ role: 'user', stable: true, messageId: id, rawMessageId: id, rawText: canonical }] } }]);
    await live.hook.flush();
    expect(rows().at(-1)?.event).toMatchObject({ text: canonical, textOrigin: 'provider' });

    // The old row's custody does not suppress a new native human UUID or its Send boundary.
    userTurn(live.document, 'canonical-next-human', 'Use this corrected scope.');
    assistantTurn(live.document, 'canonical-next-answer', []);
    startGenerating(live.document, { send: false });
    live.hook.observe(); await live.hook.flush();
    expect(emitted(live.sent, 'user_message').filter(row => row.event.messageId === 'm-canonical-next-human').at(-1)?.event)
      .toMatchObject({ text: 'Use this corrected scope.', authoredNow: true });
    expect(emitted(live.sent, 'turn_start')).toHaveLength(1);
  });

