    startGenerating(live.document, { send: false });
    const original = assistantTurn(live.document, 'late-error-helper-original', []);
    prose(live.document, original, 'late-error-helper-answer', '');
    live.hook.observe();
    await settle();
    const userProof = { turnId: 'late-error-helper-user', conversationId: providerId,
      messages: [{ role: 'user', messageId: 'm-late-error-helper-user', rawMessageId: 'm-late-error-helper-user', rawText: text }] };
    const finalProof = { turnId: 'late-error-helper-final', conversationId: providerId,
      endMessageId: 'late-error-helper-answer', messages: [
        { role: 'assistant', messageId: 'late-error-helper-answer', rawMessageId: 'late-error-helper-answer', rawText: '', renderedHtml: '<p></p>' }
      ] };
    await bindFiberTurns([{ section: user, turn: userProof }, { section: original, turn: finalProof }]);
    stopGenerating(live.document);

    // React replaces the completed section before the provider card arrives. The replacement
    // has no local turn-id tombstone, but it is still the assistant turn after this exact user.
    original.remove();
    const replacement = assistantTurn(live.document, 'late-error-helper-replacement', []);
    prose(live.document, replacement, 'late-error-helper-answer', '');
    const failure = live.document.createElement('div');
    const failureCopy = live.document.createElement('p');
