    await geometry.grow(200);
    expect(geometry.followed()).toBe(true);

    // Only a real reader gesture followed by this exact scroller moving detaches the tail.
    live.window.dispatchEvent(new live.window.WheelEvent('wheel', { deltaY: -400 }));
    geometry.scrollTo(geometry.top() - 400);
