  it('counts only the exact provider request retained by a steered response as current work', async () => {
    const conversationId = 'aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee';
    const requestId = 'wfr_exact_steered_response';
    let stream: unknown[] = [];
    live = await harness(undefined, {
      activity: () => ({ ok: true, data: { entries: [], stream, nextSince: 0, pendingTools: 0,
        userAnchors: [{ seq: 1, time: 1_787_165_090_500, messageId: 'm-older-user' }] } })
    });
    userTurn(live.document, 'older-user', 'the question before', { sent: false });
    await live.hook.pullActivity();
    userTurn(live.document, 'steer-first', 'run the import', { sent: false });
    startGenerating(live.document, { send: false });
    for (let tick = 0; tick < 3; tick++) { live.hook.observe(); await settle(); }
    const first = emitted(live.sent, 'turn_start').at(-1)!.event.turnId as string;

    // Stop alone is not the continuity proof. The correction's exact provider message keeps
    // the response request id, and /activity independently maps that id to the original turn.
    const steeringQuestion = userTurn(live.document, 'steer-second', 'also keep the tag', { sent: false });
    for (let tick = 0; tick < 3; tick++) { live.hook.observe(); await settle(); }
    expect(emitted(live.sent, 'turn_end').map(row => row.event.turnId)).toEqual([first]);
    expect(emitted(live.sent, 'turn_start')).toHaveLength(2);
    const providerProof = {
      turnId: 'provider-steering-input', conversationId,
      requests: [{ requestId, messageId: 'm-steer-second', createTime: 1_787_165_091 }],
      messages: [{ role: 'user', stable: true, messageId: 'm-steer-second',
        rawMessageId: 'm-steer-second', rawText: 'also keep the tag' }]
    };
    await bindFiberTurns([{ section: steeringQuestion, turn: providerProof }]);

    const firstWork = { seq: 101, time: live.window.Date.now(), kind: 'tool_call', turnId: first,
      requestId, tool: 'exec_command', callId: 'steer-call-1', attribution: 'request_id' };
    stream = [firstWork];
    await live.hook.pullActivity();
    expect(live.hook.activityIsCurrentWork(firstWork), 'exact provider request lost its durable owner').toBe(true);
    expect(live.hook.activityIsCurrentWork({ ...firstWork, seq: 102, turnId: 'g-another-document-0-9' }),
      'foreign local turns must remain rejected').toBe(false);
    await bindFiberTurns([{ section: steeringQuestion, turn: { ...providerProof, requests: [
      ...providerProof.requests,
      { requestId: 'wfr_ambiguous_steering', messageId: 'm-steer-second', createTime: 1_787_165_091 }
    ] } }]);
    expect(live.hook.activityIsCurrentWork(firstWork), 'ambiguous provider requests must fail closed').toBe(false);
    await bindFiberTurns([{ section: steeringQuestion, turn: providerProof }]);

    // Cross the watchdog boundary, then let the same exact provider request produce more work.
    live.advance(6 * 60_000);
    stream = [...stream, { ...firstWork, seq: 103, time: live.window.Date.now(), callId: 'steer-call-2' }];
    await live.hook.pullActivity();
    live.hook.observe();
    await settle();
    expect(emitted(live.sent, 'chat_error')
      .filter(row => /could not confirm that this turn finished/i.test(String(row.event.text))))
      .toHaveLength(0);
  });

  it('does not let delayed old-response activity refresh a fast stop-and-follow-up', async () => {
    const conversationId = 'aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee';
    const oldRequestId = 'wfr_stopped_response';
    const nextRequestId = 'wfr_real_followup';
    let stream: unknown[] = [];
    live = await harness(undefined, {
      activity: () => ({ ok: true, data: { entries: [], stream, nextSince: 0, pendingTools: 0,
        userAnchors: [{ seq: 1, time: 1_787_165_090_500, messageId: 'm-older-user' }] } })
    });
    userTurn(live.document, 'older-user', 'the question before', { sent: false });
    await live.hook.pullActivity();
    userTurn(live.document, 'stopped-first', 'run the import', { sent: false });
    startGenerating(live.document, { send: false });
    assistantTurn(live.document, 'stopped-response', []);
    live.hook.observe(); await settle();
    const first = emitted(live.sent, 'turn_start').at(-1)!.event.turnId as string;

    // The observer misses the quiet gap entirely. This has the same local booleans as steering,
    // but the provider stamps the new user message with a different response request.
    stopGenerating(live.document);
    const followup = userTurn(live.document, 'fast-real-followup', 'now check the export', { sent: false });
    startGenerating(live.document, { send: false });
    assistantTurn(live.document, 'real-followup-response', []);
    live.hook.observe(); await settle();
    const second = emitted(live.sent, 'turn_start').at(-1)!.event.turnId as string;
    expect(second).not.toBe(first);

    // A local turn stamp is not enough for request-bearing work. Until Fiber proves which
    // provider request owns this rendered question, the old request is ambiguous and must
    // fail closed even though app correlation stamped it with the current local turn.
    const delayed = { seq: 201, time: live.window.Date.now(), kind: 'tool_call', turnId: second,
      requestId: oldRequestId, tool: 'exec_command', callId: 'late-old-call', attribution: 'request_id' };
    expect(live.hook.activityIsCurrentWork(delayed), 'missing provider evidence must fail closed').toBe(false);

    await bindFiberTurns([{ section: followup, turn: {
      turnId: 'provider-real-followup', conversationId,
      requests: [{ requestId: nextRequestId, messageId: 'm-fast-real-followup', createTime: 1_787_165_092 }],
      messages: [{ role: 'user', stable: true, messageId: 'm-fast-real-followup',
        rawMessageId: 'm-fast-real-followup', rawText: 'now check the export' }]
    } }]);

    // App correlation can arrive after the local boundary and stamp the late old request onto
    // the active local turn. The contradictory provider request still has to win and reject it.
    live.advance(6 * 60_000);
    stream = [delayed];
    await live.hook.pullActivity();
    expect(live.hook.activityIsCurrentWork(delayed)).toBe(false);
    live.hook.observe(); await settle();
    expect(emitted(live.sent, 'chat_error')
      .filter(row => /could not confirm that this turn finished/i.test(String(row.event.text))))
      .toHaveLength(1);
  });

