  it.each(['resolved', 'rejected'])(
    'does not let a late old-page correlation reply erase or back off the NEW pending native call after A to B to A navigation (%s)',
    async outcome => {
    const a = 'aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee';
    const b = 'bbbbbbbb-cccc-dddd-eeee-ffffffffffff';
    const requestId = 'wfr_native_same_key_after_route_epoch_change';
    const ack = { ok: true, data: { conversationId: a, confirmed: [requestId], complete: true } };
    const release: Array<{ resolve: (answer: unknown) => void; reject: (error: Error) => void }> = [];
    live = await harness();
    live.reply.set('correlate', () => new Promise((resolve, reject) => {
      release.push({ resolve, reject });
      if (release.length > 2) resolve({ ok: false });
    }));
    const frame = () => [{ turnId: 'same-request-after-navigation', conversationId: a,
      calls: [{ messageId: 'native-same-key', tool: 'read', order: 0,
        answered: false, requestId, createTime: 1_700_000_001 }], messages: []
    }];
    try {
      await replyFiber([], frame());
      await settle();
      expect(live.sent.filter(message => message.type === 'correlate')).toHaveLength(1);
      live.window.history.pushState({}, '', `/c/${b}`);
      live.hook.observe();
      await settle();
      live.window.history.pushState({}, '', `/c/${a}`);
      live.hook.observe();
      await settle();
      await replyFiber([], frame());
      await settle();
      expect(live.sent.filter(message => message.type === 'correlate')).toHaveLength(2);
      // A's previous in-flight IPC returns after the new A epoch has already
      // claimed the SAME key. Its finally/catch must not clear or back off the
      // replacement, or a third callback can duplicate the current handshake.
      if (outcome === 'rejected') release[0]!.reject(new Error('stale old document transport lost'));
      else release[0]!.resolve(ack);
      await settle();
      await replyFiber([], frame());
      await settle();
      expect(live.sent.filter(message => message.type === 'correlate')).toHaveLength(2);
    } finally {
      for (const finish of release) finish.resolve(ack);
      await settle();
    }
  });

