  async function parkedCorePickerResume(checkpoint: string | null = 'attempted-unresolved') {
    const commandId = 'cmd-attention-core-picker';
    const text = prepareOperatorPrompt('[[CLF-RESUME:0123456789abcdef0123456789abcdef]]\n\nContinue the exact saved handoff; retain unverified results.', upper => upper - 1);
    const state = { blockPicker: true, attention: false, owner: '', redeemError: '', sends: 0 };
    live = await harness('https://chatgpt.com/?clf=' + commandId, {
      status: () => ({ connected: true, paired: true,
        browserAttentionCommandIds: state.attention ? [commandId] : [] }),
      redeem: message => {
        if (message.id !== commandId || state.owner && message.client !== state.owner || state.redeemError)
          return { ok: false, error: state.redeemError || 'command_taken' };
        state.owner = message.client;
        return { ok: true, command: { id: commandId, type: 'resume', text, agent: null,
          expiresAt: 1_700_001_000_000, coreConnector: TEST_CORE } };
      },
      compact: message => message.destinationAttempt
        ? { ok: true, data: { allowed: true, ...(checkpoint ? { destinationSend: {
          state: checkpoint, conversationId: null, messageId: null
        } } : {}) } }
        : { ok: true, data: { armed: true } },
      ack: message => ({ ok: true, final: message.status === 'sent', committed: message.status === 'sent',
        outcome: message.status })
    }, (document, dom) => {
      const profile = document.createElement('button');
      profile.dataset.testid = 'accounts-profile-button';
      profile.dataset.clfTestRendered = '1';
      document.body.append(profile);
      document.querySelector('[data-composer-navigation-target="add-context"]')!.addEventListener('click', event => {
        if (state.blockPicker) event.stopImmediatePropagation();
      }, true);
      document.querySelector('[data-testid="send-button"]')!.addEventListener('click', () => {
        state.sends++;
        const adapter = (dom.window as any).CLF_DOM;
        expect(adapter.nativeConnectorMentionIdentity()).toMatchObject({ appId: TEST_CORE.appId });
        expect(adapter.composerAuthoredText(TEST_CORE.connectorName, TEST_CORE.appId)).toBe(text);
        dom.reconfigure({ url: 'https://chatgpt.com/c/91919191-7272-4363-8454-454545454545' });
        userTurn(document, 'accepted-core-attention-resume', text, { sent: false });
      });
    });
    await settle(300);
    expect(live.sent.filter(message => message.type === 'redeem')).toHaveLength(1);
    expect(live.sent.filter(message => message.destinationAttempt)).toHaveLength(1);
    expect(live.sent.filter(message => message.destinationDispatch)).toHaveLength(0);
    expect(live.sent.filter(message => message.type === 'ack')).toEqual([
      expect.objectContaining({ id: commandId, status: 'attention',
        error: expect.stringContaining('did not expose the installed Core app') })
    ]);
    expect(state.sends).toBe(0);
    const selectCore = () => {
      state.blockPicker = false;
      live!.document.querySelector<HTMLButtonElement>('[data-composer-navigation-target="add-context"]')!.click();
      live!.document.querySelector<HTMLButtonElement>('[data-clf-test-core-option]')!.click();
      expect((live!.window as any).CLF_DOM.nativeConnectorMentionIdentity()).toMatchObject({ appId: TEST_CORE.appId });
      expect((live!.window as any).CLF_DOM.composerAuthoredText(TEST_CORE.connectorName, TEST_CORE.appId)).toBe('');
      state.attention = true;
    };
    return { commandId, text, state, selectCore };
  }

