  it.each(['unknown-checkpoint', 'dispatched-checkpoint', 'draft', 'attachment', 'foreign-app',
    'different-command', 'different-document', 'new-work', 'approval', 'signed-out', 'paused', 'already-dispatched',
    'model-unavailable', 'expired-lease', 'new-question'] as const)('keeps pre-dispatch Core-picker attention held for %s', async reason => {
    const f = await parkedCorePickerResume(reason === 'unknown-checkpoint' ? null :
      reason === 'dispatched-checkpoint' ? 'dispatched-unresolved' : 'attempted-unresolved');
    f.selectCore();
    const document = live!.document, adapter = (live!.window as any).CLF_DOM;
    const box = document.querySelector('#prompt-textarea')!;
    if (reason === 'draft') box.append(document.createTextNode('A newer human draft must remain intact.'));
    if (reason === 'foreign-app') box.querySelector('[app-mention-path]')!.setAttribute('app-mention-path', 'app://asdk_app_foreign_core');
    if (reason === 'attachment') {
      const file = document.createElement('button');
      file.setAttribute('aria-label', 'Remove file: attachment.txt'); file.dataset.clfTestRendered = '1';
      box.closest('form')!.append(file);
    }
    if (reason === 'different-command') live!.window.history.replaceState({}, '', '/?clf=another-command');
    if (reason === 'different-document') await reinjectContentRecorder(live!);
    if (reason === 'new-work') {
      const stop = document.createElement('button');
      stop.dataset.testid = 'stop-button'; stop.dataset.clfTestRendered = '1';
      box.closest('form')!.append(stop);
      userTurn(document, 'new-core-attention-question', 'A newer native request.');
    }
    if (reason === 'expired-lease') live!.advance(2_000_000);
    if (reason === 'new-question') userTurn(document, 'later-core-attention-question', 'A newer authored request.');
    if (reason === 'approval') {
      const card = document.createElement('div');
      card.dataset.codexApprovalSurface = 'true'; card.dataset.clfTestRendered = '1';
      card.innerHTML = '<button data-clf-test-rendered="1">Allow once</button>';
      document.body.append(card);
    }
    if (reason === 'signed-out') {
      const login = document.createElement('button');
      login.dataset.testid = 'login-button'; login.dataset.clfTestRendered = '1'; document.body.append(login);
    }
    if (reason === 'paused' || reason === 'already-dispatched')
      f.state.redeemError = reason === 'paused' ? 'automation_paused' : 'command_already_sent';
    if (reason === 'model-unavailable') {
      adapter.ensurePreferredAutomationModel = async () => ({ status: 'unavailable', reason: 'usage-limit' });
      adapter.selectModelSettings = async () => false;
    }
    await live!.hook.checkStatus();
    await settle(500);
    expect(f.state.sends).toBe(0);
    expect(live!.sent.filter(message => message.destinationDispatch)).toHaveLength(0);
    expect(live!.sent.some(message => message.type === 'ack' && message.status === 'sent')).toBe(false);
    if (reason === 'draft') expect(box.textContent).toContain('A newer human draft must remain intact.');
    if (['unknown-checkpoint', 'dispatched-checkpoint', 'draft', 'attachment', 'foreign-app', 'new-work',
      'approval', 'signed-out', 'expired-lease', 'new-question'].includes(reason))
      expect(live!.sent.filter(message => message.type === 'redeem')).toHaveLength(1);
  });

  it.each(['redeem', 'destination-attempt', 'destination-dispatch', 'model-confirmation'] as const)(
    'retains the original Core-picker attention custody when native work starts during %s', async phase => {
      const f = await parkedCorePickerResume();
      f.selectCore();
      const document = live!.document, adapter = (live!.window as any).CLF_DOM;
      const beginWork = () => {
        const stop = document.createElement('button');
        stop.dataset.testid = 'stop-button'; stop.dataset.clfTestRendered = '1';
        document.querySelector('#composer-form')!.append(stop);
      };
      const redeem = live!.reply.get('redeem')!, compact = live!.reply.get('compact')!;
      if (phase === 'redeem') live!.reply.set('redeem', async message => {
        const reply = await redeem(message); beginWork(); return reply;
      });
      if (phase === 'destination-attempt' || phase === 'destination-dispatch')
        live!.reply.set('compact', async message => {
          const reply = await compact(message);
          if (phase === 'destination-attempt' ? message.destinationAttempt : message.destinationDispatch) beginWork();
          return reply;
        });
      if (phase === 'model-confirmation') adapter.selectModelSettings = async (_model: string, _effort: string, current: () => boolean) => {
        beginWork(); return current();
      };
      await live!.hook.checkStatus();
      await settle(500);

      expect(f.state.sends).toBe(0);
      expect(live!.sent.filter(message => message.destinationDispatch)).toHaveLength(
        phase === 'destination-dispatch' || phase === 'model-confirmation' ? 1 : 0);
      expect(live!.sent.filter(message => message.destinationLost || message.sourceLost || message.ticket)).toHaveLength(0);
      expect(live!.sent.some(message => message.type === 'ack' && message.status === 'sent')).toBe(false);
      expect(live!.sent.filter(message => message.type === 'ack').at(-1)).toMatchObject({
        id: f.commandId, client: f.state.owner, status: 'attention'
      });
    });

