      expect(await live.runtimeMessage({ type: 'clf-recorder-ping' })).toMatchObject({ requiredFeatures: features, freshTurnProtocol: 0 });
      expect(await live.runtimeMessage({ type: 'clf-page-status' })).toMatchObject({ requiredFeatures: features });
      expect(composer.textContent).toBe('Retain my personal draft');
