  it.each(['current-frame', 'different-conversation', 'same-conversation-new-epoch'] as const)(
    'withholds prior ordinary-final metadata during reconciliation (%s)', async race => {
      let release!: (reply: unknown) => void;
      const held = new Promise(resolve => { release = resolve; });
      let reconciliationStarted = false;
      live = await harness(undefined, {
        activity: () => ({ ok: true, data: { entries: [], stream: [], job: null } }),
        compact: message => {
          if (message.sourceMessageId !== userId) return { ok: false, error: 'unknown_message' };
          reconciliationStarted = true;
          return held;
        }
      }, document => {
        // An idle background page projects cached evidence without starting a second
        // foreground scan during each activity poll.
        Object.defineProperty(document, 'visibilityState', { configurable: true, value: 'hidden' });
      });
      const diagnostic = async () => {
        await live!.hook.pullActivity();
        return live!.sent.filter(message => message.type === 'activity').at(-1)?.coreDiagnostic?.ordinaryFinal;
      };
      await replyFiber([], pair().slice(1));
      expect(await diagnostic()).toMatchObject({ questions: 0, calls: 0 });

      const next = pair();
      next[0]!.messages[0]!.rawText = '[[CLF-HANDOFF:0123456789abcdef0123456789abcdef]]\nKeep the exact saved work.';
      (next[1]!.calls as unknown[]).push({ messageId: 'private-pending-call', tool: 'read', answered: false });
      let nativeSends = 0;
      live.document.querySelector('[data-testid="send-button"]')!.addEventListener('click', () => { nativeSends += 1; });
      live.sent.length = 0;
      const refresh = replyFiber([], next);
      try {
        await vi.waitFor(() => expect(reconciliationStarted).toBe(true));
        // The newer accepted Fiber frame has already replaced the public stamps. Its
        // reconciliation is not finished, so the previous frame's counts are unknown now.
        expect(await diagnostic()).toBeNull();
        if (race !== 'current-frame') {
          live.dom.reconfigure({ url: 'https://chatgpt.com/c/bbbbbbbb-bbbb-cccc-dddd-eeeeeeeeeeee' });
          live.hook.observe(); await settle();
          if (race === 'same-conversation-new-epoch') {
            live.dom.reconfigure({ url: `https://chatgpt.com/c/${chat}` });
            live.hook.observe(); await settle();
          }
        }
      } finally {
        release({ ok: false, status: 409, data: { error: 'no_such_continuation' } });
        await refresh;
      }
      if (race === 'current-frame') {
        expect(await diagnostic()).toMatchObject({ reason: 'question-invalid', questions: 1, calls: 1,
          openCalls: 1, codeCalls: 0, openCodeCalls: 0, activeTurnMapped: false });
      } else {
        // An old reconciliation must not republish its counts in another route/epoch.
        expect(await diagnostic()).toBeNull();
        const currentChat = race === 'different-conversation'
          ? 'bbbbbbbb-bbbb-cccc-dddd-eeeeeeeeeeee' : chat;
        await replyFiber([], pair().map(turn => ({ ...turn, conversationId: currentChat })));
        expect(await diagnostic()).toMatchObject({ reason: 'associated', questions: 1, calls: 0 });
      }
      expect(nativeSends).toBe(0);
      expect(live.sent.filter(message => message.type === 'compact' &&
        (message.sourceDispatch || message.destinationDispatch || message.summary))).toEqual([]);
      expect(JSON.stringify(await diagnostic())).not.toMatch(/saved work|bounded pass|rawText|rawResult|toolArguments/);
    }
  );

  /** Execute the shipped MAIN-world producer, rather than assuming `stable` means final.
   * A normal native final has a UUID but no commentary-parent/working-turn alias. */
  const producedPair = async (logicalAlias = false, nativeMessages: Array<Record<string, unknown>> = []): Promise<Array<Record<string, any>>> => {
    const dom = new JSDOM('<!doctype html><html><body></body></html>', {
      url: `https://chatgpt.com/c/${chat}`, runScripts: 'outside-only', pretendToBeVisual: true
    });
    const window = dom.window;
    try {
      const messages = [
        { id: userId, author: { role: 'user' }, recipient: 'all',
          content: { content_type: 'text', parts: ['Continue the exact saved work.'] } },
        ...nativeMessages,
        { id: finalId, author: { role: 'assistant' }, recipient: 'all', status: 'finished_successfully', end_turn: true,
          content: { content_type: 'text', parts: ['The bounded pass is complete.'] },
          ...(logicalAlias ? { create_time: 1_700_000_000, metadata: { working_turn_id: 'native-work' } } : {}) }
      ];
      const section = window.document.createElement('section');
      section.setAttribute('data-testid', 'conversation-turn-0');
      section.setAttribute('data-turn-id', 'native-producer-turn');
      (section as unknown as Record<string, unknown>).__reactFiber$nativeFinal = {
        memoizedProps: { allMessages: messages, allGroupedMessages: [messages], conversation: { id: chat },
          turn: { id: 'native-producer-turn', messages } }, return: null
      };
      window.document.body.append(section);
      window.eval(await fs.readFile(path.join(process.cwd(), 'extension', 'fiber.js'), 'utf8'));
      const nonce = 'native-terminal-contract';
      const frame = new Promise<Record<string, any>>((resolve, reject) => {
        const timeout = globalThis.setTimeout(() => reject(new Error('the native Fiber producer never answered')), 2000);
        window.addEventListener('message', (event: any) => {
          if (event.data?.source !== 'clf-fiber-reply' || event.data.nonce !== nonce) return;
          globalThis.clearTimeout(timeout); resolve(event.data);
        });
      });
      window.dispatchEvent(new window.MessageEvent('message', {
        source: window as unknown as Window, data: { source: 'clf-fiber-ask', nonce }
      }));
      const result = await frame;
      expect(result.scanOk).toBe(true);
      expect(result.turns).toHaveLength(1);
      expect(result.turns[0]).toMatchObject({ conversationId: chat, endMessageId: finalId });
      expect(result.turns[0].messages.find((message: Record<string, unknown>) => message.role === 'user'))
        .toMatchObject({ stable: true, messageId: userId, rawMessageId: userId });
      expect(result.turns[0].messages.find((message: Record<string, unknown>) => message.role === 'assistant'))
        .toMatchObject({ stable: logicalAlias, rawMessageId: finalId,
          messageId: logicalAlias ? 'assistant:native-work::1700000000000' : finalId });
      return result.turns;
    } finally { window.close(); }
  };

