  /**
   * A stopped, interrupted or failed turn is exactly the turn a user is about to say
   * something about themselves. Only a completed answer is one to continue from.
   */
  it('does not let a Goal watch left behind free the lock the chat on screen is holding', async () => {
    const other = 'bbbbbbbb-bbbb-cccc-dddd-eeeeeeeeeeee';
    const base = goalReplies(null, 1);
    const feedActivity = base.activity;
    let parkNext = false;
    let releaseStale!: () => void;
    const staleHeld = new Promise<void>(resolve => { releaseStale = resolve; });
    live = await harness(`https://chatgpt.com/c/${CHAT}`, {
      ...base,
      activity: () => {
        if (!parkNext) return feedActivity();
        parkNext = false;
        return (async () => { await staleHeld; return feedActivity(); })();
      }
    });
    await live.hook.pullActivity();
    await settle();
    const left = assistantTurn(live.document, 'stale-watch', []);
    prose(live.document, left, 'stale-watch-final', 'Saved final answer.');
    parkNext = true;
    live.hook.noteGoalTurn({ node: left, nodes: [left], role: 'assistant' }, 'completed', 'stale-watch');
    live.advance(2_000);
    await settle(200);
    expect(await live.runtimeMessage({ type: 'clf-page-status' })).toMatchObject({ goalBusy: true });
    // The user opens another chat while that watch is still in flight, and the claim it raised
    // is retired with it.
    live.dom.reconfigure({ url: `https://chatgpt.com/c/${other}` });
    live.hook.observe();
    await settle(200);
    expect(await live.runtimeMessage({ type: 'clf-page-status' })).toMatchObject({ goalBusy: false });
    // The new chat is on the same Loop, so it takes the lock for its own watch.
    await live.hook.pullActivity();
    const current = assistantTurn(live.document, 'new-watch', []);
    prose(live.document, current, 'new-watch-final', 'Saved answer of the new chat.');
    live.hook.noteGoalTurn({ node: current, nodes: [current], role: 'assistant' }, 'completed', 'new-watch');
    await settle(50);
    expect(await live.runtimeMessage({ type: 'clf-page-status' })).toMatchObject({ goalBusy: true });
    releaseStale();
    await settle(400);
    expect(await live.runtimeMessage({ type: 'clf-page-status' })).toMatchObject({ goalBusy: true });
  });

