  it('releases the Goal send lock when the route id comes back for the same chat', async () => {
    let draft: unknown = null;
    live = await harness(`https://chatgpt.com/c/${CHAT}`, {
      ...goalReplies(),
      activity: () => ({
        ok: true,
        data: {
          entries: [], stream: [], nextSince: 0, pendingTools: 0, job: null,
          goal: { enabled: true, hasKey: true, model: MODEL, draft }
        }
      }),
      goal_ack: () => {
        draft = null;
        return { ok: true, data: { acknowledged: true } };
      }
    });
    let resume: (() => void) | undefined;
    const timer = live.window.setTimeout;
    // One-shot: only the first of these waits is this delivery's, and every later one in the
    // same test belongs to whatever the freed lock lets the Loop start next.
    live.window.setTimeout = ((fn: () => void, ms?: number) => {
      if (ms === 200 && !resume) { resume = fn; return 0; }
      return timer(fn, ms);
    }) as typeof live.window.setTimeout;
    draft = readyDraft('Continue the saved work');
    const pulling = live.hook.pullActivity();
    await settle();
    expect(resume).toBeTypeOf('function');
    // The composer stops being provably this chat's, so this delivery cannot finish.
    live.dom.reconfigure({ url: 'https://chatgpt.com/' });
    live.hook.observe();
    resume!();
    await pulling;
    await settle();
    // The same id returns in the same epoch: no branch of observe() retires anything here.
    live.dom.reconfigure({ url: `https://chatgpt.com/c/${CHAT}` });
    live.hook.observe();
    await settle();
    expect(await live.runtimeMessage({ type: 'clf-page-status' })).toMatchObject({ goalBusy: false });
    // And the Loop drives again: the next completed answer in this chat gets its own watch,
    // which is the only thing `goalBusy` decides.
    const turned = assistantTurn(live.document, 'churn-return', []);
    prose(live.document, turned, 'churn-return-final', 'The tests are green now.');
    live.hook.noteGoalTurn({ node: turned, nodes: [turned], role: 'assistant' }, 'completed', 'churn-return');
    await settle();
    expect(await live.runtimeMessage({ type: 'clf-page-status' })).toMatchObject({ goalBusy: true });
  });

  it.each([false, true])('keeps the new chat Goal lock when an older send footer resumes after its deferred ACK (navigate: %s)', async navigate => {
    const other = 'bbbbbbbb-bbbb-cccc-dddd-eeeeeeeeeeee';
    let draft: ReturnType<typeof readyDraft> | null = null;
    let footerEntered = false, parkNextB = false;
    let releaseOldAck!: () => void, releaseBWatch!: () => void;
    const oldAck = new Promise<void>(resolve => { releaseOldAck = resolve; });
    const bWatch = new Promise<void>(resolve => { releaseBWatch = resolve; });
    live = await harness(`https://chatgpt.com/c/${CHAT}`, {
      ...goalReplies(),
      activity: () => {
        if (live?.window.location.pathname === `/c/${other}`) {
          if (parkNextB) {
            parkNextB = false;
            return (async () => { await bWatch; return feed(null, 1)(); })();
          }
          return feed(null, 1)();
        }
        // Only the pre-click authorization sees new work. A already owns the
        // sending lock, so its finally must await the native-busy defer ACK.
        return feed(draft, draft && composerText(live!.document).trim() ? 1 : 0)();
      },
      goal_ack: async message => {
        if (message.nativeBusy === true) {
          footerEntered = true;
          await oldAck;
        }
        return { ok: true, data: { acknowledged: true } };
      }
    });
    const sends = watchSend(live.document);
    draft = readyDraft('Old A must remain unsent.');
    const drivingA = live.hook.pullActivity();
    try {
      await settle(400);
      expect(footerEntered).toBe(true);
      expect(await live.runtimeMessage({ type: 'clf-page-status' })).toMatchObject({ goalBusy: true });
      draft = null;
      if (navigate) {
        live.dom.reconfigure({ url: `https://chatgpt.com/c/${other}` });
        live.hook.observe();
        await settle(100);
        expect(await live.runtimeMessage({ type: 'clf-page-status' })).toMatchObject({ goalBusy: false });
        await live.hook.pullActivity();
        const current = assistantTurn(live.document, 'footer-new-watch', []);
        prose(live.document, current, 'footer-new-final', 'New B has its own unfinished work.');
        parkNextB = true;
        live.hook.noteGoalTurn({ node: current, nodes: [current], role: 'assistant' }, 'completed', 'footer-new-watch');
        live.advance(2_000);
        await settle(200);
        expect(await live.runtimeMessage({ type: 'clf-page-status' })).toMatchObject({ goalBusy: true });
      }
      releaseOldAck();
      await drivingA;
      await settle(200);
      expect(await live.runtimeMessage({ type: 'clf-page-status' })).toMatchObject({ goalBusy: navigate });
      expect(sends()).toBe(0);
      expect(acks(live).every(message => !message.messageId && message.conversationId === CHAT)).toBe(true);
      expect(live.sent.filter(message => message.response)).toEqual([]);
    } finally {
      releaseOldAck(); releaseBWatch();
      await drivingA;
    }
  });

