    expect(live.sent.filter(row => row.type === 'goal_draft')).toHaveLength(draftsBefore);
    expect(live.sent.filter(row => ['goal_ack', 'goal_prepare', 'desktop_input', 'settings_set', 'compact'].includes(row.type))).toHaveLength(0);
    waitReason = 'evidence';
