  it('removes the old chat terminal Goal card on New Chat and a concrete chat switch', async () => {
    live = await harness(
      `https://chatgpt.com/c/${CHAT}`,
      liveFeed(readyDraft('', 'no-reply')).replies
    );
    await live.hook.pullActivity();
    await settle();
    expect(live.document.querySelector('.clf-stage')).not.toBeNull();

    // New Chat has no conversation id until its first message. Recorder identity is held
    // through that ambiguous router gap, but conversation-scoped UI must leave on the tick
    // that reads the new route. Which half of the tick removes it is injectStage()'s business
    // and nobody else's: it is the one that knows a chat being opened on a goal is the id-less
    // case worth painting, and observe() second-guessing it rebuilt the panel every second.
    live.dom.reconfigure({ url: 'https://chatgpt.com/' });
    live.hook.observe();
    live.hook.injectStage();
    expect(live.document.querySelector('.clf-stage')).toBeNull();

    // Recreate the old terminal card, then prove the concrete A -> B reset also removes it.
    live.dom.reconfigure({ url: `https://chatgpt.com/c/${CHAT}` });
    live.hook.injectStage();
    expect(live.document.querySelector('.clf-stage')).not.toBeNull();
    live.dom.reconfigure({ url: 'https://chatgpt.com/c/bbbbbbbb-cccc-dddd-eeee-ffffffffffff' });
    live.hook.observe();
    expect(live.document.querySelector('.clf-stage')).toBeNull();
  });

  it.each(['d', 'hello', 'Saved handoff: preserve this work'])('replaces only authorized composer residue (%s)', async (existingText) => {
    let sends = () => 0;
    let pending: Record<string, unknown> | null = {
      replyId: 'saved-final-with-user-draft', turnId: 't-1', acceptedAt: 1003, eventSeq: 15
    };
    let draft: Record<string, unknown> | null = readyDraft('what about the tests');
    live = await harness(
      `https://chatgpt.com/c/${CHAT}`,
      {
        ...goalReplies(),
        activity: () => ({ ok: true, data: {
          entries: [], stream: [], nextSince: 0, pendingTools: 0, job: null,
          goal: { enabled: true, own: true, mode: 'loop', afterTurn: true, hasKey: true, model: MODEL,
            pending, draft }
        } }),
        goal_ack: () => {
          pending = null;
          draft = null;
          return { ok: true, data: { acknowledged: true } };
        }
      },
      (document) => {
        sends = watchSend(document);
        const mine = document.createElement('p');
        mine.textContent = existingText;
        document.querySelector('#prompt-textarea')!.append(mine);
        document.querySelector('[data-testid="send-button"]')!.addEventListener('click', () => {
          userTurn(document, 'accepted-preserved-goal', prepareOperatorPrompt('what about the tests', upper => upper - 1), { sent: false });
          document.querySelector('#prompt-textarea')!.textContent = '';
        });
      }
    );

    await live.hook.pullActivity();
    await settle();
    if (existingText !== 'Saved handoff: preserve this work') {
      expect(sends()).toBe(1);
      expect(acks(live).length).toBeGreaterThan(0);
      expect(operatorPromptBody(composerText(live.document))).toBe('');
      return;
    }
    expect(sends()).toBe(0);
    expect(operatorPromptBody(composerText(live.document))).toBe(existingText);
    expect(acks(live)).toHaveLength(0);
    expect(live.document.querySelector('.clf-stage')?.textContent).toContain('unsent draft or attachment');

    const recovery = await live.runtimeMessage({
      type: 'clf-collect-goal-now',
      conversationId: CHAT
    }) as Record<string, unknown>;
    expect(recovery).toMatchObject({
      ok: true,
      pending: true,
      // The page does not pretend a blocked composer accepted/sent anything. The explicit
      // composer fence lets the repair owner defer it without classifying it as no progress.
      claimed: false,
      composerBlocked: true,
      working: false,
      settledPending: true
    });
    expect(Object.values(recovery)).not.toContain(existingText);
    expect(sends()).toBe(0);
    expect(operatorPromptBody(composerText(live.document))).toBe(existingText);

    live.document.querySelector('#prompt-textarea')!.textContent = '';
    await live.hook.pullActivity();
    await settle();
    expect(sends()).toBe(1);
    // The accepted user message can race an activity pull carrying the same ready
    // draft. Receipt replay is intentional; only the irreversible send is exactly once.
    expect(acks(live).length).toBeGreaterThan(0);
    expect(new Set(acks(live).map(message => `${message.conversationId}:${message.token}`)).size).toBe(1);
  });

