  it('respects long provider opening Retry-After and retains backoff for malformed or shorter delays', async () => {
    live = await harness('https://chatgpt.com/');
    for (const retryAfterMs of [undefined, '37000', NaN, Infinity, -1, 0, 15_000]) {
      expect(live.hook.openRetryWait({ data: { retryAfterMs } }, 4)).toBe(60_000);
    }
    expect(live.hook.openRetryWait({ data: { retryAfterMs: 37_000 } }, 0)).toBe(37_000);
    expect(live.hook.openRetryWait({ retryAfterMs: 120_000 }, 4)).toBe(120_000);
    // A genuine account/provider two-hour reset must not be polled at the old one-hour cap.
    expect(live.hook.openRetryWait({ data: { retryAfterMs: 7_200_000 } }, 4)).toBe(7_200_000);
    expect(live.hook.openRetryWait({ data: { retryAfterMs: 2_147_483_648 } }, 4)).toBe(2_147_483_647);
  });

  it('honors Retry-After for a rate-limited New Chat opening and sends once', async () => {
    let attempts = 0;
    live = await harness('https://chatgpt.com/', {
      settings_get: () => ({
        ok: true,
        data: {
          context: { auto: false, threshold: 400_000, warn: 400_000, limit: 533_000 },
          goal: { enabled: false, hasKey: true, model: MODEL, objective: '', blocked: '' }
        }
      }),
      goal_open: () => {
        attempts += 1;
        return attempts === 1
          ? {
              ok: false,
              status: 502,
              data: { error: 'rate_limited: Provider returned error', retryable: true, retryAfterMs: 37_000 }
            }
          : { ok: true, data: { reply: 'rewrite the parser in rust', model: MODEL } };
      }
    });
    await live.hook.pullActivity();
    const sends = watchSend(live.document);
    live.document.querySelector('[data-testid="send-button"]')!.addEventListener('click', () => {
      startGenerating(live!.document);
    });
    // The opening waits on the same quarter-minute clock as the in-chat loop, not on a
    // one-second courtesy pause: a provider rate limit lasts longer than that, and a run
    // started from an empty New Chat has no later turn to try again from.
    const held = live;
    const timer = held.window.setTimeout;
    const wakes: Array<() => void> = [];
    held.window.setTimeout = ((fn: () => void, ms?: number) => {
      if (ms !== undefined && ms >= held.hook.GOAL_RETRY_MS && ms <= held.hook.GOAL_RETRY_CAP_MS) {
        wakes.push(fn);
        return 0;
      }
      return timer(fn, ms);
    }) as typeof held.window.setTimeout;
    live.hook.injectControl();
    live.hook.toggleMenu();
    (live.document.querySelector('.clf-menu-goal-link') as HTMLButtonElement).click();
    const box = live.document.querySelector('[data-clf-goal-input]') as HTMLTextAreaElement;
    box.value = 'rewrite the parser in rust';
    box.dispatchEvent(new live.window.Event('input', { bubbles: true }));

    (live.document.querySelector('.clf-menu-goal-save') as HTMLButtonElement).click();
    await settle(400);

    expect(attempts).toBe(1);
    expect(wakes, 'a rate-limited opening waits for the Goal retry clock').toHaveLength(1);
    expect(live.document.body.textContent).toContain('Retrying Goal in 37 seconds');
    expect(live.document.body.textContent).not.toContain('The goal loop stopped');
    wakes[0]!();
    await settle(800);

    expect(attempts).toBe(2);
    expect(sends()).toBe(1);
    expect(operatorPromptBody(composerText(live.document))).toBe('rewrite the parser in rust');
  });

